import{_ as t,o,c as a,a2 as n}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"What do the messages in the adapter log mean?","description":"","frontmatter":{"order":6,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/03.referenz/06.log-meldungen.md"},"headers":[],"relativePath":"adapter/esphome/referenz/log-meldungen.md","filePath":"adapter/esphome/referenz/log-meldungen.md","lastUpdated":1795571670000}'),d={name:"adapter/esphome/referenz/log-meldungen.md"};function r(i,e,s,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="what-do-the-messages-in-the-adapter-log-mean" tabindex="-1">What do the messages in the adapter log mean? <a class="header-anchor" href="#what-do-the-messages-in-the-adapter-log-mean" aria-label="Permalink to &quot;What do the messages in the adapter log mean?&quot;">​</a></h1><p><a id="log-full-errors-connections-drop"></a></p><h2 id="why-is-the-log-full-of-errors-when-connections-drop-and-reconnect" tabindex="-1">Why is the log full of errors when connections drop and reconnect? <a class="header-anchor" href="#why-is-the-log-full-of-errors-when-connections-drop-and-reconnect" aria-label="Permalink to &quot;Why is the log full of errors when connections drop and reconnect?&quot;">​</a></h2><p>If a device is offline, the adapter tries again at every reconnect interval. It reports most errors once per outage, some on every attempt:</p><table tabindex="0"><thead><tr><th>Message</th><th>how often</th></tr></thead><tbody><tr><td><code>Device &lt;IP&gt; is unreachable</code>, <code>… requires an encryption key …</code></td><td>once per outage</td></tr><tr><td><code>Connection to device &lt;IP&gt; lost …</code>, <code>Timeout connecting …</code>, <code>Network not ready …</code></td><td>once per outage</td></tr><tr><td><code>ESPHome client … disconnected</code></td><td>on every disconnect</td></tr><tr><td><code>Device &lt;IP&gt; is not ready to connect yet, the adapter tries again</code></td><td>on every attempt</td></tr><tr><td><code>Device &lt;IP&gt; rejected the API password</code></td><td>on every attempt</td></tr><tr><td><code>ESPHome client &lt;IP&gt; &lt;error&gt;</code></td><td>on every attempt</td></tr></tbody></table><p>This makes the log quieter:</p><ol><li>Fix the cause, e.g. switch the device on or correct the credentials.</li><li>If you no longer need the device, delete it in the tab &quot;Devices&quot;.</li><li>If it is often off for a long time, raise &quot;Reconnect interval (seconds)&quot; in the main settings.</li></ol><p>You cannot pause single devices.</p><p><strong>See also:</strong> <a href="./einstellungen#reconnect-settings-exist-happens-device">Connection settings</a> · <a href="./../anleitungen/geraete-verwalten#delete-device-completely-objects-come">Delete a device</a></p><p><a id="deserializebinary-assertion-failed-bad-format"></a></p><h2 id="what-do-deserializebinary-assertion-failed-bad-format-and-invalid-wire-type-mean" tabindex="-1">What do &quot;deserializeBinary&quot;, &quot;Assertion failed&quot;, &quot;Bad format&quot; and &quot;Invalid wire type&quot; mean? <a class="header-anchor" href="#what-do-deserializebinary-assertion-failed-bad-format-and-invalid-wire-type-mean" aria-label="Permalink to &quot;What do &quot;deserializeBinary&quot;, &quot;Assertion failed&quot;, &quot;Bad format&quot; and &quot;Invalid wire type&quot; mean?&quot;">​</a></h2><p>These messages come from the library the adapter uses to talk to the device (<code>@2colors/esphome-native-api</code>). They mean that adapter and device do not match, usually in the encryption key, less often because the firmware sends messages the library does not know.</p><p>The adapter turns a missing key, a wrong API password and network errors into its own messages. All other errors appear unchanged as <code>ESPHome client &lt;IP&gt; &lt;error&gt;</code> in the log, again with every connection attempt.</p><table tabindex="0"><thead><tr><th>Log message</th><th>What is behind it</th><th>What to do</th></tr></thead><tbody><tr><td><code>Device &lt;IP&gt; requires an encryption key</code></td><td>The device uses encryption, the adapter has no key.</td><td>Enter the key from <code>api:</code> → <code>encryption:</code> → <code>key:</code> for the device.</td></tr><tr><td><code>Bad format. Expected 1 at the begin</code></td><td>The adapter has a key, but the device answers unencrypted.</td><td>Turn on encryption in the YAML and flash again, or remove the key in the adapter.</td></tr><tr><td><code>Bad format. Expected 0 at the begin</code></td><td>Something other than the ESPHome API answers at the address.</td><td>Check that the device really runs at this address.</td></tr><tr><td><code>Handshake failure</code></td><td>The device rejected the key.</td><td>Compare the key in YAML and adapter character by character.</td></tr><tr><td><code>Device &lt;IP&gt; sent a message (type &lt;number&gt;) the adapter cannot read yet</code></td><td>The firmware sends a message the library does not know, the connection is closed. Usually the device&#39;s ESPHome version is newer than the adapter knows.</td><td>Step 3 below.</td></tr><tr><td><code>deserializeBinary</code>, <code>Assertion failed</code>, <code>Invalid wire type</code></td><td>Same cause as the line above.</td><td>Steps below.</td></tr></tbody></table><h3 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h3><ol><li>Check that the device&#39;s YAML has an <code>api:</code> section. Without it the adapter cannot talk to the device.</li><li>Compare the key under <code>api:</code> → <code>encryption:</code> → <code>key:</code> with the one in the adapter. To do so, open &quot;Change connection settings&quot; for the device in the &quot;Devices&quot; tab. If the device has no encryption, the field must be empty.</li><li>If you just moved the firmware to a new ESPHome version, the library may not know its messages yet. Then a newer adapter version helps, or the older firmware for now.</li><li>If the message keeps coming, delete the device in the &quot;Devices&quot; tab and add it again with address and key.</li><li>It worked when the log shows <code>ESPHome client &lt;IP&gt; connected</code> and <code>esphome.0.&lt;device&gt;.info._online</code> turns <code>true</code>.</li></ol><p>A device that answers a ping can still be offline for the adapter. A ping only checks the network, these messages concern the ESPHome API on port 6053.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erstes-geraet#encryption-key-not-accepted">Why is my encryption key not accepted?</a> · <a href="./../erste-schritte/erstes-geraet#api-password-still-work-esphome">API password and ESPHome 2026.1</a> · <a href="./../anleitungen/geraete-verwalten#delete-device-completely-objects-come">Deleting a device completely</a> · <a href="./einstellungen#reconnect-settings-exist-happens-device">Reconnect settings</a></p><p><a id="constantly-see-adapter-connections-device"></a></p><h2 id="why-do-i-constantly-see-adapter-connections-in-the-device-log" tabindex="-1">Why do I constantly see adapter connections in the device log? <a class="header-anchor" href="#why-do-i-constantly-see-adapter-connections-in-the-device-log" aria-label="Permalink to &quot;Why do I constantly see adapter connections in the device log?&quot;">​</a></h2><p>The adapter keeps a permanent connection to every device over the ESPHome API. In the device log it shows up with the name of the ioBroker host. It checks the connection at the ping interval and re-establishes it after a drop at the reconnect interval.</p><p>One connection per adapter restart is normal. If you constantly see new connections, the connection keeps dropping. Check the Wi-Fi of the device then and raise the ping attempts under &quot;Connection behavior for known devices&quot;.</p><p>The adapter writes the messages of the device itself into its log only at log level &quot;debug&quot;.</p><p><strong>See also:</strong> <a href="./einstellungen#reconnect-settings-exist-happens-device">Connection settings</a></p>',24)])])}const m=t(d,[["render",r]]);export{g as __pageData,m as default};
